package com.callagent.gateway.sip

import java.io.File
import java.security.cert.CertificateException
import java.security.cert.X509Certificate
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * The trust configuration for SIP over TLS.
 *
 * The certificates used here are generated by `tools/gen-pbx-cert.sh` and
 * checked in as fixtures: a CA and a server certificate it signed, plus an
 * unrelated CA with a certificate of its own.  They are test material, not
 * secrets.
 */
class SipTrustTest {

    private fun fixture(name: String): ByteArray =
        checkNotNull(javaClass.classLoader?.getResourceAsStream(name)) { "missing fixture: $name" }
            .use { it.readBytes() }

    private fun certificates(name: String): List<X509Certificate> =
        SipTrust.parseCertificates(fixture(name))

    // ── PEM parsing ────────────────────────────────────────────────────────

    @Test
    fun parsesASingleCertificate() {
        val certs = certificates("test-ca.pem")
        assertEquals(1, certs.size)
    }

    @Test
    fun parsesSeveralCertificatesFromOneFile() {
        val combined = fixture("test-ca.pem") + "\n".toByteArray() + fixture("other-ca.pem")
        val certs = SipTrust.parseCertificates(combined)
        assertEquals(2, certs.size)
    }

    @Test
    fun ignoresTextAroundTheCertificateBlock() {
        val noisy = ("A private key exported by some tool\n" +
            "-----BEGIN PRIVATE KEY-----\nnot a certificate\n-----END PRIVATE KEY-----\n"
            ).toByteArray() + fixture("test-ca.pem")
        val certs = SipTrust.parseCertificates(noisy)
        assertEquals(1, certs.size)
    }

    @Test
    fun rejectsAFileThatHoldsNoCertificate() {
        try {
            SipTrust.parseCertificates("this is not a certificate".toByteArray())
            fail("expected a CertificateException")
        } catch (e: CertificateException) {
            assertTrue(e.message!!.contains("no PEM certificate"))
        }
    }

    @Test
    fun rejectsAnEmptyFile() {
        try {
            SipTrust.parseCertificates(ByteArray(0))
            fail("expected a CertificateException")
        } catch (e: CertificateException) {
            // expected
        }
    }

    @Test
    fun rejectsACertificateBlockThatIsNotBase64() {
        val broken = "-----BEGIN CERTIFICATE-----\nnot base64 at all!!\n-----END CERTIFICATE-----"
        try {
            SipTrust.parseCertificates(broken.toByteArray())
            fail("expected a CertificateException")
        } catch (e: CertificateException) {
            // expected
        }
    }

    // ── The composite trust decision ───────────────────────────────────────

    @Test
    fun acceptsAChainSignedByTheImportedCa() {
        val trust = SipTrust.withImported(certificates("test-ca.pem"))
        val server = certificates("test-server.pem")
        // Must not throw: the chain is signed by the imported CA.
        trust.trustManager.checkServerTrusted(arrayOf(server.first()), "RSA")
    }

    @Test
    fun rejectsAChainSignedByAnUnrelatedCa() {
        val trust = SipTrust.withImported(certificates("test-ca.pem"))
        val otherServer = certificates("other-server.pem")
        try {
            trust.trustManager.checkServerTrusted(arrayOf(otherServer.first()), "RSA")
            fail("expected the unrelated chain to be rejected")
        } catch (e: CertificateException) {
            assertTrue(e.message!!.contains("not trusted"))
        }
    }

    @Test
    fun consultedThePlatformStoreBeforeTheImportedOne() {
        val trust = SipTrust.withImported(certificates("test-ca.pem"))
        val server = certificates("test-server.pem")
        trust.trustManager.checkServerTrusted(arrayOf(server.first()), "RSA")
        assertTrue("the platform trust store must be consulted", trust.platformConsulted)
    }

    @Test
    fun importedCertificatesArePartOfTheAcceptedIssuers() {
        val imported = certificates("test-ca.pem")
        val trust = SipTrust.withImported(imported)
        val issuers = trust.trustManager.acceptedIssuers.toList()
        assertTrue(issuers.containsAll(imported))
    }

    @Test
    fun thePlatformStoreIsStillTrustedAlongsideTheImport() {
        val trust = SipTrust.withImported(certificates("test-ca.pem"))
        val platformIssuers = SipTrust.platformTrustManager()?.acceptedIssuers.orEmpty()
        assertTrue("the platform CAs must remain trusted", platformIssuers.isNotEmpty())
        val issuers = trust.trustManager.acceptedIssuers.toList()
        assertTrue(issuers.containsAll(platformIssuers.take(3)))
    }

    @Test
    fun withoutAnImportOnlyThePlatformStoreCounts() {
        val trust = SipTrust.platformOnly()
        assertEquals(0, trust.importedCount)
        val otherServer = certificates("other-server.pem")
        try {
            trust.trustManager.checkServerTrusted(arrayOf(otherServer.first()), "RSA")
            fail("a self-signed test chain must not be trusted by the platform store")
        } catch (e: CertificateException) {
            // expected
        }
    }

    // ── Storage ────────────────────────────────────────────────────────────

    @Test
    fun importedCaSurvivesANewInstanceAndCanBeRemoved() {
        val dir = File(System.getProperty("java.io.tmpdir"), "sip-trust-test-${System.nanoTime()}")
        val file = File(dir, "ca.pem")
        val storage = FileCaStorage(file)

        assertTrue("a fresh store is empty", storage.isEmpty())
        assertEquals(null, storage.read())

        storage.append(fixture("test-ca.pem"))
        assertTrue(storage.isEmpty().not())
        assertNotNull(storage.read())

        // A second reader — the next launch of the app — sees the same CAs.
        val trust = SipTrustProvider.current(FileCaStorage(file))
        assertEquals(1, trust.importedCount)

        // Appending keeps what was there and adds the second CA.
        storage.append(fixture("other-ca.pem"))
        val trustAfterSecondImport = SipTrustProvider.current(FileCaStorage(file))
        assertEquals(2, trustAfterSecondImport.importedCount)

        storage.clear()
        assertTrue(storage.isEmpty())
        val trustAfterClear = SipTrustProvider.current(FileCaStorage(file))
        assertEquals(0, trustAfterClear.importedCount)

        file.delete()
        dir.delete()
    }

    @Test
    fun aSecondImportKeepsTheFirstOne() {
        val dir = File(System.getProperty("java.io.tmpdir"), "sip-trust-append-${System.nanoTime()}")
        val storage = FileCaStorage(File(dir, "ca.pem"))
        storage.append(fixture("test-ca.pem"))
        storage.append(fixture("other-ca.pem"))
        val certs = SipTrust.parseCertificates(storage.read()!!)
        assertEquals(2, certs.size)
        dir.deleteRecursively()
    }
}
